param(
    [string]$RepositoryRoot = (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
)

$ErrorActionPreference = 'Stop'
$messageRoot = Join-Path $RepositoryRoot 'OmniCell\Libraries\Source\AOtomation.Messaging\SmokeLounge.AOtomation.Messaging\Messages'
$enumPath = Join-Path $messageRoot 'N3MessageType.cs'
$outputRoot = Join-Path $RepositoryRoot 'OmniCell\Documentation\protocol'
$packetRoot = Join-Path $outputRoot 'packets'

New-Item -ItemType Directory -Force $packetRoot | Out-Null
Get-ChildItem -LiteralPath $packetRoot -Filter '*.html' -File | Remove-Item -Force

function Html([object]$value) {
    return [System.Net.WebUtility]::HtmlEncode([string]$value)
}

# The evidence and the field cells are prose that has always been written with a
# little markup in it - <em> round a variant name, <br> for a list, &#39; for an
# apostrophe, &quot; round a feedback string. Html encodes all of that, so what
# reached the page was the literal text "&#39;" and "<br>", on fifty of the
# hundred and sixty three pages. This escapes what needs escaping and leaves
# that markup alone: an ampersand that does not begin an entity becomes one, and
# a less-than that does not open one of four tags becomes one.
function Rich([object]$value) {
    $text = [string]$value
    if ($text -eq '') { return '' }
    $text = [regex]::Replace(
        $text,
        '&(?!(?:amp|lt|gt|quot|apos|nbsp|rarr|larr|hellip|mdash|ndash|#[0-9]+|#x[0-9A-Fa-f]+);)',
        '&amp;')
    $text = [regex]::Replace($text, '<(?!/?(?:br|em|strong|code)\s*/?>)', '&lt;')
    return $text
}

function Slug([string]$value) {
    return ([regex]::Replace($value, '([a-z0-9])([A-Z])', '$1-$2')).ToLowerInvariant()
}

function StatusLabel([string]$status) {
    switch ($status) {
        'complete' { return 'every byte identified' }
        'values' { return 'unknown byte meanings remain' }
        'schema' { return 'field schema only' }
        'absent' { return 'not in this client' }
        default { return 'byte meanings not mapped yet' }
    }
}

# Ids we carry that the client of 18.8.62 has no class for. The id on the wire
# is a hash of the client's own class name and the client looks it up in the
# registry n3InfoItemRemote_t::Register builds - 135 classes in Gamecode.dll
# and three more in N3.dll - so a name that hashes to nothing is a message this
# client cannot receive. These thirteen are worse than that: nothing in any
# client binary hashes to their ids at all, not even an unregistered class. They
# came out of CellAO's older table and there is nothing here to identify, so
# they do not count against the total.
