        @(45,4,'<em>operation 5</em> loot access enabled','0 or 1','The sender normalises its Boolean argument at 0x10018525','proven'),
        @(49,4,'<em>operation 5</em> loot target type','caller-supplied Identity.Type','The third N3Msg_SetLootAccess operand, passed through whole','proven'),
        @(53,4,'<em>operation 5</em> loot target instance','caller-supplied Identity.Instance','The third N3Msg_SetLootAccess operand, passed through whole','proven')
    )
    Variants=@(
        @('Create raid','operation 1','one empty operand; 41 bytes','N3Msg_CreateRaid, and .raid create'),
        @('List','operation 2','empty operands; 41 bytes','.raid list only - no export sends it'),
        @('List local','operation 3','never sent','.raid listlocal is handled in the client at 0x10040930'),
        @('Move member','operation 4','member instance + destination team; 41 bytes','N3Msg_MoveRaidMember, and .raid move'),
        @('Set loot access','operation 5','all three operand pairs; 57 bytes','N3Msg_SetLootAccess, and .raid lootaccess'),
