$known['WeaponItemFullUpdate'] = @{
    Status='complete'; Direction='server &rarr; client'; Length='119 for a seven stat weapon, plus 8 per extra stat'; Evidence='Every byte is identified, and almost none of it is this packet. WeaponItemFullUpdateIIR_t::ReadSubClass at Gamecode.dll 0x100A2CAB is three instructions: it calls SimpleItemFullUpdateIIR_t::ReadSubClass at 0x100A1661 and returns what it says. No tail, no version of its own, no extra field - the two messages are one format under two ids. Its WriteSubClass is a bare return, so the client never sends this. That is not how it was modelled, and the difference matters. The stat list was written out as a fixed run of named fields, which froze one weapon''s stats into the format: AcgItemLevel, AcgItemTemplateId, AcgItemTemplateId2, MultipleCount and StaticInstance were not values but the stat ids 701, 702, 703, 412 and 23, and the field called Unknown6 in front of them was the X3F1 count. The old note on the trailing stat pairs could see that the two populations lined up exactly with Unknown6, 10090 against 8072, and put it down to a correlation; those are simply the counts for nine stats and for seven. Two more fields were split across their own boundaries. What was called Unknown4, a short, is the high half of the state machine instance, and what was called Unknown5 is its low half followed by the inventory id and the body location - which is why that field read 262 and 264 so often, since 262 is 0x106: inventory id 1, body location 6, a weapon in the right hand. It round-tripped throughout, because the leftover fields soaked up whatever was left and the bytes came back in order. It would not have survived a weapon whose stats arrived in another order, and it could not express the four captured copies that carry eight stats rather than seven or nine. Nor could it have read a weapon lying on the ground: the old model had no position block at all, and the gate for one is a zero owner instance, which every captured weapon avoids by being carried. On the family layout all 4,386 captured copies still round-trip byte for byte, and the fields now read as they should - body location 6 and 8 for the two hands, stat counts of seven, eight and nine, and an empty name. WeaponItemFullUpdateWithDelayStatsMatchesRetailCaptureByteForByte reproduces a captured nine stat weapon from scratch.'
    Tests='WeaponItemFullUpdateWithDelayStatsMatchesRetailCaptureByteForByte'
    Fields=@(
        @(29,4,'Message version','11 in every captured copy','Checked against the static at 0x101C2160 by the shared SimpleItemFullUpdate reader','proven'),
        @(33,4,'Owner identity type','CanbeAffected in 3,661 of 4,386','Who is holding the weapon','proven'),
        @(37,4,'Owner identity instance','396 distinct across the captures','Zero would make the position below present. No captured weapon has one - they are all being carried','proven'),
        @(41,12,'Coordinates','no captured copy carries them','XYZ floats, present only when the owner instance is 0','proven'),
        @(53,16,'Heading','same condition','quaternion XYZW','proven'),
        @('next',4,'Playfield','2150461, 655, 2150799 and 710','','proven'),
        @('next',4,'State machine identity type','always 1000015','The identity type of a state machine; the client builds the same identity from stat 450, statemachine','proven'),
        @('next',4,'State machine identity instance','always 0','A weapon has no state machine, where a door carries 1','proven'),
        @('next',1,'Inventory id','1 in 4,312 of 4,386','Stat 55, inventoryid','proven'),
        @('next',1,'Body location','6 in 3,601 and 8 in 612','Stat 220, currbodylocation - which hand the weapon is in','proven'),
        @('next',4,'Stat count','X3F1: (entries + 1) * 0x3F1','Seven, eight or nine across the captures','proven'),
        @('next','8 per stat','Stats','stat id then value','flags, staticinstance, 701, 702, 703, multiplecount and energy, plus itemdelay and rechargedelay on the nine stat weapons','proven'),
        @('last','4 + length','Name','empty in every captured copy','The length counts a terminating null when there is a string at all; an empty name is four zero bytes','proven')
    )
}

foreach ($entry in $known.GetEnumerator()) {
    $layout = $entry.Value
    $declaredSampleLength = if ($layout.SampleLength) { [int]$layout.SampleLength } elseif ($layout.Length -match '^\d+$') { [int]$layout.Length } else { $null }
    if ($layout.Sample -and $null -ne $declaredSampleLength) {
        $sampleLength = ($layout.Sample -split '\s+').Count
        if ($sampleLength -ne $declaredSampleLength) {
            throw ('Sample length mismatch for {0}: declared {1}, contains {2} bytes' -f $entry.Key, $declaredSampleLength, $sampleLength)
        }
    }
}

$enumText = Get-Content -Raw -LiteralPath $enumPath
$matches = [regex]::Matches($enumText, '(?m)^\s*([A-Za-z][A-Za-z0-9_]*)\s*=\s*0x([0-9A-Fa-f]+)')
$packets = foreach ($match in $matches) {
    [pscustomobject]@{ Name=$match.Groups[1].Value; Opcode=('0x' + $match.Groups[2].Value.ToUpperInvariant()); Slug=(Slug $match.Groups[1].Value) }
}

$schemaFiles = Get-ChildItem -LiteralPath $messageRoot -Filter '*.cs' -Recurse
$schemas = @{}
foreach ($file in $schemaFiles) {
    $text = Get-Content -Raw -LiteralPath $file.FullName
    $contract = [regex]::Match($text, 'N3MessageType\.([A-Za-z][A-Za-z0-9_]*)')
    if (!$contract.Success) { continue }
    $members = [regex]::Matches($text, '(?s)\[AoMember\((\d+)\)\]\s*public\s+([A-Za-z0-9_<>\[\], ]+)\s+([A-Za-z0-9_]+)\s*\{') | ForEach-Object {
        [pscustomobject]@{ Order=[int]$_.Groups[1].Value; Type=$_.Groups[2].Value.Trim(); Name=$_.Groups[3].Value }
    }
    if ($members.Count) { $schemas[$contract.Groups[1].Value] = @($members | Sort-Object Order) }
}

