        @(58,4,'Milliseconds since previous move','0 in 56% of copies, else 9..58826','Matched the measured gap to within 60ms in 97% of 2,665 client packets','proven'),
        @(62,4,'Reserved','0 in all 3,000 captured copies','No captured copy carries anything here','proven'),
        @(66,4,'Tilt about the heading''s X','0.0 in all 3,000 captured copies','The second angle of the same call, about the axis (1, 0, 0) rotated by the sent heading - built at 0x10004F51. Read and validated exactly like the field above','proven')
