$css = @'
:root{color-scheme:dark;--bg:#0b1018;--panel:#121a26;--line:#27364a;--ink:#e8eef8;--muted:#91a0b5;--cyan:#56d4dd;--green:#65d68b;--amber:#f2bd5b;--red:#ff7b72}*{box-sizing:border-box}body{margin:0;font:14px/1.5 system-ui,Segoe UI,sans-serif;color:var(--ink);background:var(--bg)}header{padding:20px 24px;background:#101824;border-bottom:1px solid var(--line)}main{max-width:1250px;margin:auto;padding:24px}h1{margin:0;font-size:23px}h2{margin-top:28px}.sub{color:var(--muted)}a{color:var(--cyan)}.back{display:inline-block;margin-bottom:18px;text-decoration:none}.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:20px;margin-bottom:16px}.completed-panel{border-color:#2f6946}.completed-panel h2{margin-top:0;color:var(--green)}.badges,.legend{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 16px}.badge,.legend span{border:1px solid var(--line);border-radius:99px;padding:3px 9px}.complete{color:var(--green)}.values{color:var(--amber)}.schema,.missing{color:var(--muted)}.absent{color:var(--muted);opacity:.6}.unresolved,.failed{color:var(--red)}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{color:var(--muted)}td:first-child,td:nth-child(2),td:nth-child(4),code{font-family:Consolas,monospace}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:9px}.card{display:block;padding:11px;border:1px solid var(--line);border-radius:8px;text-decoration:none;background:#0d1520}.completed-panel .card{border-color:#2f6946}.card:hover{border-color:var(--cyan)}.card code{display:block;color:var(--muted)}input{width:100%;padding:11px;margin:16px 0;border:1px solid var(--line);border-radius:8px;background:#0a111b;color:var(--ink)}.bytegrid{display:grid;grid-template-columns:repeat(16,minmax(34px,1fr));gap:3px;overflow:auto}.byte{padding:5px 2px;text-align:center;border:1px solid var(--line);border-radius:4px;font:12px Consolas,monospace}.byte small{display:block;color:#64758d;font-size:9px}.notice{padding:10px 12px;border-left:3px solid var(--amber);background:#0c1420}.proof{border-left-color:var(--cyan)}@media(max-width:700px){main{padding:14px}table{font-size:12px}}
'@
Set-Content -LiteralPath (Join-Path $outputRoot 'protocol.css') -Value $css -Encoding UTF8

# The index is a worklist, so the two grids do not overlap: green at the
# top, and everything that is not green below it, worst first. Listing a
# finished packet twice made the remaining work impossible to count by eye.
$order = @{ 'values' = 0; 'schema' = 1; 'missing' = 2; 'absent' = 3 }
$states = @{}
foreach ($packet in $packets) {
    $states[$packet.Name] = if ($absent -contains $packet.Name) { 'absent' } elseif ($known.ContainsKey($packet.Name)) { $known[$packet.Name].Status } elseif ($schemas.ContainsKey($packet.Name)) { 'schema' } else { 'missing' }
}
# An id that is not a message in this client is not outstanding work, so
# it is counted and listed apart: carried = green + still to do, and that
# subtraction has to hold on the page.
$remaining = $packets | Where-Object { $states[$_.Name] -ne 'complete' -and $states[$_.Name] -ne 'absent' } | Sort-Object @{ Expression = { $order[$states[$_.Name]] } }, Name
$cards = foreach ($packet in $remaining) {
    $state = $states[$packet.Name]
    '<a class="card" data-search="' + (Html ($packet.Name + ' ' + $packet.Opcode)).ToLowerInvariant() + '" href="packets/' + $packet.Slug + '.html"><strong>' + (Html $packet.Name) + '</strong><code>' + $packet.Opcode + '</code><span class="' + $state + '">' + (Html (StatusLabel $state)) + '</span></a>'
}
$notHere = $packets | Where-Object { $states[$_.Name] -eq 'absent' } | Sort-Object Name
$notHereCards = foreach ($packet in $notHere) {
    '<a class="card" data-search="' + (Html ($packet.Name + ' ' + $packet.Opcode)).ToLowerInvariant() + '" href="packets/' + $packet.Slug + '.html"><strong>' + (Html $packet.Name) + '</strong><code>' + $packet.Opcode + '</code><span class="absent">' + (Html (StatusLabel 'absent')) + '</span></a>'
}
$valuesCount = @($states.Values | Where-Object { $_ -eq 'values' }).Count
$schemaCount = @($states.Values | Where-Object { $_ -eq 'schema' }).Count
$missingCount = @($states.Values | Where-Object { $_ -eq 'missing' }).Count
$completedCards = foreach ($packet in $packets) {
    if ($known.ContainsKey($packet.Name) -and $known[$packet.Name].Status -eq 'complete') {
        '<a class="card" data-search="' + (Html ($packet.Name + ' ' + $packet.Opcode)).ToLowerInvariant() + '" href="packets/' + $packet.Slug + '.html"><strong>' + (Html $packet.Name) + '</strong><code>' + $packet.Opcode + '</code><span class="complete">' + (Html (StatusLabel 'complete')) + '</span></a>'
    }
}
$completeCount = @($known.Values | Where-Object { $_.Status -eq 'complete' }).Count
# Not the hand-written $absent list: a $known entry can mark an id absent
# too, and AcgQuest does - so count the resolved states instead.
$carriedCount = $packets.Count - @($notHere).Count
$index = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OmniCell AO Protocol Index</title><link rel="stylesheet" href="protocol.css"></head><body><header><h1>OmniCell AO Protocol Index</h1><div class="sub">' + $carriedCount + ' packets this client carries &middot; ' + $completeCount + ' with every byte identified &middot; ' + @($notHere).Count + ' ids that are not messages here</div></header><main><div class="panel"><h2 style="margin-top:0">The other half</h2><p>These are the messages. What makes the client send one is usually a slash command, and the client carries those too - <a href="commands.html">every command this client knows</a>, which of them reach the game, and what each one asks the engine for.</p></div><div class="panel completed-panel"><h2>Every byte identified (' + $completeCount + ')</h2><div class="grid">' + ($completedCards -join '') + '</div></div><div class="panel"><h2 style="margin-top:0">Still to do (' + @($remaining).Count + ' of ' + $carriedCount + ')</h2><p class="sub">' + $completeCount + ' green and ' + @($remaining).Count + ' to go: ' + $valuesCount + ' amber, ' + $schemaCount + ' modelled but not mapped, ' + $missingCount + ' not started. Worst first; green is in the panel above and is not repeated here.</p><p class="notice">Green means every byte position has a known meaning. It does not mean every possible gameplay value has already appeared in a retained capture. Amber means one or more byte meanings are still unknown. Gray means byte-by-byte mapping has not started. Red is reserved for an actual contradiction or failing test. A packet marked not in this client is one whose id nothing in any 18.8.62 binary hashes to; those are counted out of the total rather than held against it.</p><div class="legend"><span class="complete">Green: every byte identified</span><span class="values">Amber: unknown meanings remain</span><span class="missing">Gray: not mapped yet</span><span class="absent">Gray: not in this client</span><span class="failed">Red: actual problem</span></div><input id="filter" placeholder="Filter the remaining packets by name or opcode…" autofocus><div class="grid" id="grid">' + ($cards -join '') + '</div></div></div><div class="panel"><h2 style="margin-top:0">Not messages in this client (' + @($notHere).Count + ')</h2><p class="sub">Ids you cannot receive: either nothing in any 18.8.62 binary answers to them, or the class that does is abstract. Counted out of the total rather than held against it, and not work. Each page says which.</p><div class="grid">' + ($notHereCards -join '') + '</div></main><script>document.querySelector("#filter").addEventListener("input",e=>{let q=e.target.value.toLowerCase();document.querySelectorAll(".card").forEach(x=>x.hidden=q&&!x.dataset.search.includes(q))})</script></body></html>'
Set-Content -LiteralPath (Join-Path $outputRoot 'index.html') -Value $index -Encoding UTF8


# A green packet whose table still has an unresolved row is a contradiction, and
# five of them had drifted into the set by 2026-09-11 - one of them opening with
# "Every byte is identified" above eleven rows that were not. Green means every
# byte position has a known meaning; if a row says otherwise, the row wins.
$contradictions = foreach ($name in $known.Keys) {
    $entry = $known[$name]
    if ($entry.Status -ne 'complete' -or -not $entry.Fields) { continue }
    # A Fields list of one row collapses to that row's own cells, so a single
    # field entry would otherwise report six unresolved rows made of characters.
    $rows = @($entry.Fields)
    if ($rows[0] -isnot [array]) { $rows = @(,$rows) }
    $open = @($rows | Where-Object { $_[5] -ne 'proven' })
    if ($open.Count -gt 0) { $name + ' (' + $open.Count + ')' }
}
if ($contradictions) {
    Write-Warning ('Green with unresolved rows: ' + ($contradictions -join ', '))
}

$primitiveWidth = @{ 'byte'=1; 'sbyte'=1; 'short'=2; 'ushort'=2; 'int'=4; 'uint'=4; 'float'=4; 'long'=8; 'ulong'=8; 'double'=8; 'Identity'=8; 'Vector3'=12; 'Quaternion'=16 }
foreach ($packet in $packets) {
    $layout = $known[$packet.Name]
    $status = if ($layout) { $layout.Status } elseif ($schemas.ContainsKey($packet.Name)) { 'schema' } else { 'missing' }
    $direction = if ($layout) { $layout.Direction } else { 'not yet audited' }
    $length = if ($layout) { $layout.Length } else { 'not yet proven' }
    $evidence = if ($layout) { $layout.Evidence } elseif ($schemas.ContainsKey($packet.Name)) { 'A serializer schema exists, but its current-client byte layout and values have not yet been capture-verified.' } else { 'Opcode is cataloged; no current serializer body schema has been accepted as evidence.' }
    $evidence = $headerProof + ' Packet body: ' + $evidence
    $fields = @($envelope)
    if ($layout) { $fields += @($layout.Fields) }
    elseif ($schemas.ContainsKey($packet.Name)) {
        $offset = 29
        foreach ($member in $schemas[$packet.Name]) {
            $width = $primitiveWidth[$member.Type]
            if (!$width) { $width = 'variable' }
            $fields += ,@($offset,$width,$member.Name,'unverified',('Serializer type: ' + $member.Type),'unresolved')
            if ($width -is [int]) { $offset += $width } else { $offset = 'dynamic' }
        }
    }
    $rows = foreach ($field in $fields) { '<tr><td>'+(Rich $field[0])+'</td><td>'+(Rich $field[1])+'</td><td>'+(Rich $field[2])+'</td><td>'+(Rich $field[3])+'</td><td>'+(Rich $field[4])+'</td><td class="'+(Html $field[5])+'">'+(Html $field[5])+'</td></tr>' }
    $sample = ''
    if ($layout -and $layout.Sample) {
        $bytes = $layout.Sample -split '\s+'
        $cells = for ($i=0; $i -lt $bytes.Count; $i++) { '<div class="byte"><small>'+('{0:D2}' -f $i)+'</small>'+$bytes[$i]+'</div>' }
        $sample = '<h2>Exact captured sample</h2><div class="bytegrid">'+($cells -join '')+'</div>'
    }
    $variants = ''
    if ($layout -and $layout.Variants) {
        $variantRows = foreach ($variant in $layout.Variants) { '<tr><td>'+(Rich $variant[0])+'</td><td>'+(Rich $variant[1])+'</td><td>'+(Rich $variant[2])+'</td><td>'+(Rich $variant[3])+'</td></tr>' }
        $variants = '<h2>Observed action variants</h2><table><thead><tr><th>Action</th><th>Source</th><th>Destination</th><th>Evidence</th></tr></thead><tbody>'+($variantRows -join '')+'</tbody></table>'
    }
    $tests = if ($layout -and $layout.Tests) { '<h2>Exact-byte tests</h2><p><code>'+(Rich $layout.Tests)+'</code></p>' } else { '' }
    $body = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+(Html $packet.Name)+' · OmniCell Protocol</title><link rel="stylesheet" href="../protocol.css"></head><body><header><h1>'+(Html $packet.Name)+' <code>'+$packet.Opcode+'</code></h1><div class="sub">AO 18.8.x protocol evidence</div></header><main><a class="back" href="../index.html">← Back to packet index</a><div class="panel"><div class="badges"><span class="badge '+$status+'">'+(Html (StatusLabel $status))+'</span><span class="badge">'+(Html $direction)+'</span><span class="badge">'+(Html $length)+' bytes</span></div><p class="notice proof">'+(Rich $evidence)+'</p><h2>Byte layout</h2><table><thead><tr><th>Offset</th><th>Width</th><th>Field</th><th>Observed value</th><th>Meaning</th><th>Evidence</th></tr></thead><tbody>'+($rows -join '')+'</tbody></table>'+$variants+$tests+$sample+'</div></main></body></html>'
    Set-Content -LiteralPath (Join-Path $packetRoot ($packet.Slug + '.html')) -Value $body -Encoding UTF8
}

Write-Output ('Generated protocol index and ' + $packets.Count + ' packet pages at ' + $outputRoot)
